$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Split-Path -Parent $PSScriptRoot));$prefix=$root.TrimEnd('\')+'\'
function R318([string]$v,[switch]$Leaf){$p=if([IO.Path]::IsPathRooted($v)){[IO.Path]::GetFullPath($v)}else{[IO.Path]::GetFullPath((Join-Path $root $v))};if(-not$p.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw 'R318_OUTSIDE_ROOT'};if($Leaf-and-not(Test-Path -LiteralPath $p -PathType Leaf)){throw 'R318_MISSING'};$p}
