function Dist318($a,$b){[Math]::Sqrt(([double]$a.GRIP_X-[double]$b.GRIP_X)*([double]$a.GRIP_X-[double]$b.GRIP_X)+([double]$a.GRIP_Y-[double]$b.GRIP_Y)*([double]$a.GRIP_Y-[double]$b.GRIP_Y))}
