$planner=R318 'scripts/plan_special_text_peer_normal_restore_v2.py' -Leaf;$loader=R318 'scripts/cad_rot_netload_manifest_exact_v2.ps1' -Leaf;$builder=R318 'scripts/build_inline_observed_cad_command_v3.ps1' -Leaf;$observer=R318 'scripts/cad_rot_send_command_observed_v12.ps1' -Leaf;$receipt=Join-Path $run 'controller_receipt.json';if(Test-Path $receipt){throw 'R318_RECEIPT_EXISTS'}
$timings=[ordered]@{};$started=Get-Date;$moveStarted=$false
function Step318([string]$name,[scriptblock]$operation){$s=[Diagnostics.Stopwatch]::StartNew();try{&$operation}finally{$s.Stop();$script:timings[$name]=[int]$s.ElapsedMilliseconds}}
function Observed318([string]$label,[string]$commandText){
 $business=Join-Path $run ($label+'_business.txt');$progress=Join-Path $run ($label+'_progress.tsv');$command=Join-Path $run ($label+'_observed.txt')
 [IO.File]::WriteAllText($business,$commandText,[Text.UTF8Encoding]::new($false));$built=&$builder -BusinessCommandPath $business -ProgressPath $progress -OutputPath $command
 if([string]$built.status-cne'PASS'){throw ('R318_BUILD_'+$label)}
 $out=&$observer -DocumentName $DocumentName -CommandPath $command -ProcessId $ProcessId -WindowHandle $WindowHandle -OwnerStatePath $ownerPath -ProgressPath $progress -ObservationDirectory (Join-Path $run ($label+'_observation')) -DocumentBindTimeoutSeconds 12 -StartAckTimeoutSeconds 25 -CommandCompletionTimeoutSeconds $TimeoutSeconds
 if([string]$out.status-cne'PASS'-or-not[bool]$out.ack_received-or-not[bool]$out.complete_received-or[int]$out.retry_count-ne0){throw ('R318_OBSERVED_'+$label)};$out
}
try{
 $owner=Get-Content $ownerPath -Raw -Encoding UTF8|ConvertFrom-Json;$proc=Get-Process -Id $ProcessId -ErrorAction Stop
 if([string]$owner.status-cne'ready'-or[int]$owner.process_id-ne$ProcessId-or[long]$owner.main_window_handle-ne$WindowHandle-or[IO.Path]::GetFileName([string]$owner.target_dwg)-cne$DocumentName-or-not$proc.Responding-or@(Get-Process acad -ErrorAction SilentlyContinue).Count-ne1){throw 'R318_OWNER'}
