 $planningGrips=$before;$recoveryMode=$false;if(-not[string]::IsNullOrWhiteSpace($RecoveryBaselineGripsPath)-or-not[string]::IsNullOrWhiteSpace($RecoveryCorruptGripsPath)){if([string]::IsNullOrWhiteSpace($RecoveryBaselineGripsPath)-or[string]::IsNullOrWhiteSpace($RecoveryCorruptGripsPath)){throw 'R320_RECOVERY_PAIR_REQUIRED'};$recoveryBaseline=R318 $RecoveryBaselineGripsPath -Leaf;$recoveryCorrupt=R318 $RecoveryCorruptGripsPath -Leaf;$freshRows=@(Import-Csv $before -Delimiter ([char]9) -Encoding UTF8);$corruptRows=@(Import-Csv $recoveryCorrupt -Delimiter ([char]9) -Encoding UTF8);$freshMap=@{};$corruptMap=@{};foreach($row in $freshRows){$freshMap[("$(([string]$row.HANDLE).ToUpperInvariant())/$($row.GRIP_INDEX)")]=$row};foreach($row in $corruptRows){$corruptMap[("$(([string]$row.HANDLE).ToUpperInvariant())/$($row.GRIP_INDEX)")]=$row};if((($freshMap.Keys|Sort-Object)-join'|')-cne(($corruptMap.Keys|Sort-Object)-join'|')){throw 'R320_CORRUPT_KEYS_CHANGED'};$currentStateDrift=0.0;foreach($key in $freshMap.Keys){$d=Dist318 $freshMap[$key] $corruptMap[$key];if($d-gt$currentStateDrift){$currentStateDrift=$d}};if($currentStateDrift-gt1e-6){throw ('R320_LIVE_NOT_RUN319_CORRUPT_STATE='+$currentStateDrift)};$planningGrips=$recoveryBaseline;$recoveryMode=$true};$plan=Join-Path $run 'special_text_peer_normal_plan.tsv';$summary=Join-Path $run 'special_text_peer_normal_plan.json'
 Step318 'peer_normal_plan'{&$PythonPath $planner --mapping $mapping --grips $planningGrips --current-grips $before --geometry $geometry --text-bboxes $bboxes --formula $formula --output-plan $plan --output-summary $summary|Out-Null;if($LASTEXITCODE-ne0){throw 'R318_PLAN_TOOL'}}
 $p=@(Import-Csv $plan -Delimiter ([char]9) -Encoding UTF8);if($p.Count-ne1-or[int]$p[0].GRIP_INDEX-ne4-or[string]$p[0].STATUS-cne'PASS'){throw 'R318_PLAN_INVALID'}
 $target=([string]$p[0].NATIVE_HANDLE).ToUpperInvariant();$currentRows=@(Import-Csv $before -Delimiter ([char]9) -Encoding UTF8);$currentG4=@($currentRows|Where-Object{([string]$_.HANDLE).ToUpperInvariant()-ceq$target-and[int]$_.GRIP_INDEX-eq4});if($currentG4.Count-ne1){throw 'R320_CURRENT_GRIP4_MISSING'};$deltaX=[double]$p[0].DX;$deltaY=[double]$p[0].DY;if([Math]::Abs(([double]$currentG4[0].GRIP_X+$deltaX)-[double]$p[0].MOVE_X)-gt1e-6-or[Math]::Abs(([double]$currentG4[0].GRIP_Y+$deltaY)-[double]$p[0].MOVE_Y)-gt1e-6){throw 'R320_DELTA_ALGEBRA_INVALID'};$moveReport=Join-Path $run 'grip4_move_report.tsv';$after=Join-Path $run 'native_grips_after.tsv';$culture=[Globalization.CultureInfo]::InvariantCulture
 $moveCommand='CXGRIPMOVE'+"`n"+$target+"`n4`n"+$deltaX.ToString('R',$culture)+"`n"+$deltaY.ToString('R',$culture)+"`n0`n"+$moveReport+"`nCXNATIVEGRIPINVENTORY`n"+$after+"`n"
 if(-not$moveCommand.StartsWith('CXGRIPMOVE',[StringComparison]::Ordinal)-or-not$moveCommand.Contains('CXNATIVEGRIPINVENTORY')-or$moveCommand-match'\$null=Observed318|scriptblock|function\s+Step318'){throw 'R319_MOVE_PAYLOAD_INVALID'};$moveStarted=$true;Step318 'grip4_move_and_inventory'{$null=Observed318 'grip4_move' $moveCommand};foreach($file in @($moveReport,$after)){if(-not(Test-Path $file -PathType Leaf)){throw 'R318_MOVE_OUTPUT_MISSING'}}
 $br=@(Import-Csv $before -Delimiter ([char]9) -Encoding UTF8);$ar=@(Import-Csv $after -Delimiter ([char]9) -Encoding UTF8);$bm=@{};$am=@{}
 foreach($row in $br){$bm[("$(([string]$row.HANDLE).ToUpperInvariant())/$($row.GRIP_INDEX)")]=$row};foreach($row in $ar){$am[("$(([string]$row.HANDLE).ToUpperInvariant())/$($row.GRIP_INDEX)")]=$row}
 $beforeKeys=($bm.Keys|Sort-Object)-join'|';$afterKeys=($am.Keys|Sort-Object)-join'|';if($beforeKeys-cne$afterKeys){throw 'R318_GRIP_KEYS_CHANGED'}
 $maxFrozen=0.0;foreach($key in $bm.Keys){$d=Dist318 $bm[$key] $am[$key];$parts=$key-split'/';if($parts[0]-ceq$target-and[int]$parts[1]-eq4){continue};if($d-gt$maxFrozen){$maxFrozen=$d}}
 if($maxFrozen-gt1e-6){throw ('R318_FROZEN_GRIP_DRIFT='+$maxFrozen)}
 $g4=$am[($target+'/4')];$targetError=[Math]::Sqrt(([double]$g4.GRIP_X-[double]$p[0].MOVE_X)*([double]$g4.GRIP_X-[double]$p[0].MOVE_X)+([double]$g4.GRIP_Y-[double]$p[0].MOVE_Y)*([double]$g4.GRIP_Y-[double]$p[0].MOVE_Y));if($targetError-gt1e-6){throw ('R318_TARGET_ERROR='+$targetError)}
 Step318 'regen'{$null=Observed318 'regen' "_.REGEN`n"}
 Step318 'preview_module_preload'{$null=&$loader -DocumentName $DocumentName -ManifestPath $previewManifest -ProcessId $ProcessId -WindowHandle $WindowHandle -OwnerStatePath $ownerPath -CompletionTimeoutSeconds 20}
 $cap=Join-Path $run 'capture';[IO.Directory]::CreateDirectory($cap)|Out-Null;$canvas=Join-Path $cap 'document_preview_full_canvas.png';$previewJson=Join-Path $cap 'document_preview_receipt.json'
 Step318 'document_preview'{$null=Observed318 'document_preview' ("CXCADDOCUMENTPREVIEWCAPTUREV1`n"+$canvas+"`n"+$previewJson+"`n")}
 if(-not(Test-Path $canvas -PathType Leaf)-or-not(Test-Path $previewJson -PathType Leaf)){throw 'R318_PREVIEW_MISSING'};$pr=Get-Content $previewJson -Raw -Encoding UTF8|ConvertFrom-Json
 if([string]$pr.status-cne'PASS'-or[string]$pr.backend-cne'AUTOCAD_DOCUMENT_CAPTURE_PREVIEW_IMAGE'){throw 'R318_PREVIEW_INVALID'}
 $result=[ordered]@{schema_version=2;controller_version='V4_MATURE_PLANNER_DX_DY_CONTRACT';status='PASS__ONE_DYNAMIC_SPECIAL_TEXT_GRIP4_RESTORED_TO_ADJACENT_PEER_NORMAL_GAP__DIMENSION_CURVE_AND_OTHER_GRIPS_FROZEN__REGEN_PREVIEW_READY';formula_id='CAD-SPECIAL-TEXT-PEER-NORMAL-RESTORE-V1';target_handle=$target;reference_handle=[string]$p[0].REFERENCE_NATIVE_HANDLE;recovery_mode=$recoveryMode;planner_output_semantics='DX_DY_WCS_DELTA_VECTOR';cxgripmove_input_semantics='WCS_DELTA_VECTOR';sent_delta_x=$deltaX;sent_delta_y=$deltaY;current_gap_h=[double]$p[0].CURRENT_GAP_H;target_gap_h=[double]$p[0].TARGET_GAP_H;commanded_grip=4;frozen_grip_maximum_drift=$maxFrozen;target_point_error=$targetError;move_send_count=1;pre_inventory_count=1;post_inventory_count=1;regen_count=1;capture_count=1;save_count=0;retry_count=0;visual=[ordered]@{path=$canvas;sha256=(Get-FileHash $canvas -Algorithm SHA256).Hash;backend='AUTOCAD_DOCUMENT_CAPTURE_PREVIEW_IMAGE'};stage_timings_ms=$timings;elapsed_ms=[int]((Get-Date)-$started).TotalMilliseconds;cross_structure_dwg='UNVERIFIED';next_gate='USER_VISUAL_REVIEW_SPECIAL_TEXT_ONLY'}
 W318 $receipt $result;[pscustomobject]$result
}catch{$result=[ordered]@{schema_version=1;status='FAILED_OR_BLOCKED__NO_RETRY';detail=$_.Exception.Message;move_started=$moveStarted;save_count=0;retry_count=0;stage_timings_ms=$timings;elapsed_ms=[int]((Get-Date)-$started).TotalMilliseconds;next_gate='PROJECT_REVIEW_NEW_READY_ONLY'};W318 $receipt $result;throw}
